`timescale 1ns / 1ps

module conv_layer (
    input  wire        clk,
    input  wire        reset,
    input  wire        valid_in,
    input  wire [7:0]  pixel_in,
    
    output wire        valid_out,
    // The 4 parallel feature maps generated by the 4 filters
    output wire [7:0]  feature_0,
    output wire [7:0]  feature_1,
    output wire [7:0]  feature_2,
    output wire [7:0]  feature_3
);

    // 1. Internal Wires
    wire        lb_valid_out;
    wire [71:0] sliding_window; // The 9 pixels from the Line Buffer
    
    // Valid signals from the 4 MAC units (they will all fire simultaneously)
    wire mac_v0, mac_v1, mac_v2, mac_v3;
    assign valid_out = mac_v0; // If one is valid, they are all valid

    // 2. The Weight Registers (Distributed ROM)
    // We load all 36 weights (4 filters * 9 weights) directly into logic cells
    reg [7:0] weight_rom [0:35];
    
    initial begin
        $readmemh("vajra_conv_weights_final.hex", weight_rom);
    end

    // Pack the 8-bit arrays into 72-bit wires for the MAC units
    // Filter 0 gets weights 0-8, Filter 1 gets 9-17, etc.
    wire [71:0] w0 = {weight_rom[8],  weight_rom[7],  weight_rom[6],  weight_rom[5],  weight_rom[4],  weight_rom[3],  weight_rom[2],  weight_rom[1],  weight_rom[0]};
    wire [71:0] w1 = {weight_rom[17], weight_rom[16], weight_rom[15], weight_rom[14], weight_rom[13], weight_rom[12], weight_rom[11], weight_rom[10], weight_rom[9]};
    wire [71:0] w2 = {weight_rom[26], weight_rom[25], weight_rom[24], weight_rom[23], weight_rom[22], weight_rom[21], weight_rom[20], weight_rom[19], weight_rom[18]};
    wire [71:0] w3 = {weight_rom[35], weight_rom[34], weight_rom[33], weight_rom[32], weight_rom[31], weight_rom[30], weight_rom[29], weight_rom[28], weight_rom[27]};

    // 3. Instantiate the Line Buffer (The Fuel Pump)
    line_buffer #(
        .WIDTH(32)
    ) LB_Inst (
        .clk(clk),
        .reset(reset),
        .valid_in(valid_in),
        .pixel_in(pixel_in),
        .valid_out(lb_valid_out),
        .window_out(sliding_window) // This wire feeds all 4 MACs
    );

    // 4. Instantiate the 4 Parallel MAC Units (The Engine)
    
    // Filter 0
    mac_unit MAC_0 (
        .clk(clk),
        .reset(reset),
        .valid_in(lb_valid_out),
        .pixels_in(sliding_window),
        .weights_in(w0),            // Feed it weight set 0
        .valid_out(mac_v0),
        .pixel_out(feature_0)
    );

    // Filter 1
    mac_unit MAC_1 (
        .clk(clk),
        .reset(reset),
        .valid_in(lb_valid_out),
        .pixels_in(sliding_window),
        .weights_in(w1),            // Feed it weight set 1
        .valid_out(mac_v1),
        .pixel_out(feature_1)
    );

    // Filter 2
    mac_unit MAC_2 (
        .clk(clk),
        .reset(reset),
        .valid_in(lb_valid_out),
        .pixels_in(sliding_window),
        .weights_in(w2),            // Feed it weight set 2
        .valid_out(mac_v2),
        .pixel_out(feature_2)
    );

    // Filter 3
    mac_unit MAC_3 (
        .clk(clk),
        .reset(reset),
        .valid_in(lb_valid_out),
        .pixels_in(sliding_window),
        .weights_in(w3),            // Feed it weight set 3
        .valid_out(mac_v3),
        .pixel_out(feature_3)
    );

endmodule